    var dots=$$('#r4Dots button[data-k]'),pz=$id('r4Pz');
    function paint(tt){var f=fit(cvs[act]);if(!f)return;drawScene(cur,f.c,f.w,f.h,tt,TH());}
    function labels(){var s=SC[cur];setT('r4CapN','0'+(cur+1));setT('r4CapT',s.cap);setT('r4Title',s.ttl);setT('r4ChAt',s.chip[0]);setT('r4ChAs',s.chip[1]);setT('r4Smp',s.smp);
      sw($id('r4Cap'));sw($id('r4Title'));sw($id('r4ChA'));
      dots.forEach(function(b,i){b.classList.toggle('on',i===cur);b.classList.toggle('done',i<cur);b.setAttribute('aria-selected',i===cur);var ii=$('i',b);if(ii)ii.style.setProperty('--p',i===cur&&R?1:0);});}
    function go(k){k=(k+5)%5;var old=cvs[act];act=1-act;cvs[act].classList.add('on');old.classList.remove('on');cur=k;el=0;labels();paint(R?DUR:0);}
    function tickF(now){if(!last)last=now;var dt=Math.min(64,now-last);last=now;if(!(paused||hover))el+=dt;
      if(el>=DUR){go(cur+1);return;}paint(el);var ii=$('i',dots[cur]);if(ii)ii.style.setProperty('--p',(el/DUR).toFixed(3));}
    var run=loop(tickF);
